arguments.command:
for f in /root/.env /root/project/.env /usr/lib/node_modules/openclaw/node_modules/bottleneck/.env; do
  printf '\n===== %s =====\n' "$f"
  awk '
    /^[[:space:]]*($|#)/ { print; next }
    /^[[:space:]]*(export[[:space:]]+)?[A-Za-z_][A-Za-z0-9_]*[[:space:]]*=/ {
      line=$0
      sub(/=.*/, "=<REDACTED>", line)
      print line
      next
    }
    { print "<REDACTED_LINE>" }
  ' "$f"
done
